import math
def count_cool_pairs_small_alpha_v2(k, alpha):
    cool_pairs = []
    limit_m = int(2/alpha) + 1
    limit_n = int(1/alpha) + 1
    for m in range(1, limit_m):
        for n in range(1, limit_n):
            x_m = math.floor(m * alpha)
            x_n = math.floor(n * alpha)
            if m * (x_n + 1) - n * x_m == k:
                is_cool = True
                if m > n:
                    x_m_minus_n = math.floor((m-n) * alpha)
                    if (m-n) * (x_n + 1) - n * x_m_minus_n == k:
                        is_cool = False
                elif n > m:
                    x_n_minus_m = math.floor((n-m) * alpha)
                    if m * (x_n_minus_m + 1) - (n-m) * x_m == k:
                        is_cool = False
                if is_cool:
                    cool_pairs.append((m, n))
    return len(cool_pairs)

